def transform(grid):
 h=len(grid); w=len(grid[0]); out=[[0]*w for _ in range(h)]; seen=set()
 for r in range(h):
  for c in range(w):
   if not grid[r][c] or (r,c) in seen: continue
   color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); pts=[]
   while stack:
    y,x=stack.pop(); pts.append((y,x))
    for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
      seen.add((a,b)); stack.append((a,b))
   t=min(y for y,x in pts); b=max(y for y,x in pts); l=min(x for y,x in pts); rr=max(x for y,x in pts)
   if b-t>=2 and rr-l>=2:
    for y in range(t,b+1):
     for x in range(l,rr+1):
      if y in (t,b) or x in (l,rr): out[y][x]=color
 return out

